@extends('layouts.app') @section('title','Пропуска общежития') @section('content')<a href="{{route('dormitory.index')}}">← Общежитие</a><h1 class="h4">🎫 QR-пропуска проживающих</h1><p class="text-secondary">В QR хранится только случайный токен. ФИО и комната загружаются с сервера после проверки.</p>@foreach($rows as $x)<div class="card mb-2"><div class="card-body d-flex justify-content-between align-items-center"><div><b>{{$x->last_name}} {{$x->first_name}}</b><br><small>{{$x->pass_id?'пропуск активен':'пропуск не выпущен'}}</small></div><form method="post" action="{{route('dormitory.pass.issue',$x->student_id)}}">@csrf<button class="btn btn-outline-primary">{{$x->pass_id?'Перевыпустить':'Выпустить'}}</button></form>@if($x->token)<div class="pass-token d-none">{{$x->token}}</div><div class="qr" data-token="{{$x->token}}"></div>@endif</div></div>@endforeach<script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script><script>document.querySelectorAll('.qr').forEach(x=>new QRCode(x,{text:x.dataset.token,width:96,height:96}))</script>@endsection